import { readFileSync } from 'node:fs';

// Generated by Go; never select expected authority from tool input or version strings.
const expected = JSON.parse(readFileSync(new URL('./runtime-contract.json', import.meta.url), 'utf8'));

function sameProjection(actual, wanted) {
  if (actual === wanted) return true;
  if (actual === null || wanted === null || typeof actual !== 'object' || typeof wanted !== 'object') return false;
  if (Array.isArray(actual) !== Array.isArray(wanted)) return false;
  if (Array.isArray(wanted)) return actual.length === wanted.length && wanted.every((item, i) => sameProjection(actual[i], item));
  const keys = Object.keys(wanted).sort();
  const actualKeys = Object.keys(actual).sort();
  return keys.length === actualKeys.length && keys.every((key, i) => key === actualKeys[i] && sameProjection(actual[key], wanted[key]));
}

// Only this bounded, generated shape is accepted. No arbitrary JSON re-encoding,
// hash recomputation, model-supplied digest, schema inference, or SemVer fallback.
export function runtimeContractIdentity(response) {
  if (!response || typeof response !== 'object' || Array.isArray(response)) throw new Error('malformed runtime contract');
  const { instance_id: instanceID, ...projection } = response;
  if (typeof instanceID !== 'string' || !instanceID.trim() || instanceID.length > 128) throw new Error('missing or malformed server instance identity');
  if (!sameProjection(projection, expected)) throw new Error('runtime contract does not match the generated Go projection');
  return instanceID;
}

export const runtimeContractID = expected.contract_id;
